"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[5693],{740(e,t,n){n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>l,default:()=>u,frontMatter:()=>d,metadata:()=>r,toc:()=>h});const r=JSON.parse('{"id":"part1-enterprise-ai-delivery/hld-service-selection","title":"HLD Service Selection (GCP): Exec Document Q&A Pilot \u2014 Choices, Alternatives, Enterprise Delays","description":"This tutorial converts our service-selection discussion into a High-Level Design section you can drop into an Architecture Review Pack. It uses concrete GCP services, includes alternatives considered, and highlights e...","source":"@site/docs/part1-enterprise-ai-delivery/07-hld-service-selection.mdx","sourceDirName":"part1-enterprise-ai-delivery","slug":"/part1-enterprise-ai-delivery/07-hld-service-selection","permalink":"/tutorials/part1-enterprise-ai-delivery/07-hld-service-selection","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":7,"frontMatter":{"title":"HLD Service Selection (GCP): Exec Document Q&A Pilot \u2014 Choices, Alternatives, Enterprise Delays","slug":"/part1-enterprise-ai-delivery/07-hld-service-selection","description":"This tutorial converts our service-selection discussion into a High-Level Design section you can drop into an Architecture Review Pack. It uses concrete GCP services, includes alternatives considered, and highlights e...","sidebar_label":"7. HLD and service selection","pagination_label":"7. HLD and service selection","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"6. Architecture reference design","permalink":"/tutorials/part1-enterprise-ai-delivery/06-architecture-reference-design"},"next":{"title":"8. After HLD: next steps","permalink":"/tutorials/part1-enterprise-ai-delivery/08-after-hld-next-steps"}}');var i=n(4848),s=n(8453),a=n(8172);const o=JSON.parse('{"sourcePath":"part1-enterprise-ai-delivery/07-hld-service-selection.html","route":"/part1-enterprise-ai-delivery/07-hld-service-selection","kind":"chapter","partId":"part1","partLabel":"Part I - Enterprise AI Delivery Lifecycle","accent":"blue","heading":"HLD Service Selection (GCP): Exec Document Q&A Pilot","title":"HLD Service Selection (GCP): Exec Document Q&A Pilot \u2014 Choices, Alternatives, Enterprise Delays","description":"This tutorial converts our service-selection discussion into a High-Level Design section you can drop into an Architecture Review Pack. It uses concrete GCP services, includes alternatives considered, and highlights e...","readingMinutes":8,"bodyClass":"","normalizeMath":false,"toc":[{"id":"principles","label":"1) HLD decision principles (what we decide now vs later)"},{"id":"architecture","label":"2) Reference architecture (GCP-aligned)"},{"id":"services","label":"3) GCP service choices (what we pick, why, alternatives, and constraints)"},{"id":"delays","label":"4) Enterprise delays & critical path (what usually takes longest)"},{"id":"howtopresent","label":"5) How to present this in an architecture review"}],"html":"<div class=\\"container\\">\\n    \\n    <p class=\\"lead\\">\\n      This tutorial converts our service-selection discussion into a <strong>High-Level Design</strong> section you can drop into\\n      an Architecture Review Pack. It uses concrete <strong>GCP services</strong>, includes <strong>alternatives considered</strong>,\\n      and highlights <strong>enterprise/internal delays</strong> (approvals, patterns, gates) that often dominate timelines.\\n    </p>\\n\\n    <ul class=\\"toc\\">\\n      <li><a href=\\"#principles\\">HLD decision principles</a></li>\\n      <li><a href=\\"#architecture\\">Reference architecture</a></li>\\n      <li><a href=\\"#services\\">Service choices (with alternatives)</a></li>\\n      <li><a href=\\"#delays\\">Enterprise delays &amp; critical path</a></li>\\n      <li><a href=\\"#howtopresent\\">How to present in review</a></li>\\n    </ul>\\n\\n    <h2 id=\\"principles\\">1) HLD decision principles (what we decide now vs later)</h2>\\n    <div class=\\"card\\">\\n      <div class=\\"grid2\\">\\n        <div class=\\"box\\">\\n          <div class=\\"k\\">Decide at HLD</div>\\n          <ul>\\n            <li>Major components and trust boundaries</li>\\n            <li>Security posture (identity, access enforcement, secrets)</li>\\n            <li>Data boundary: what can go to the LLM</li>\\n            <li>Core services that create long lead-time dependencies</li>\\n            <li>Audit/observability requirements</li>\\n          </ul>\\n        </div>\\n        <div class=\\"box\\">\\n          <div class=\\"k\\">Defer to LLD</div>\\n          <ul>\\n            <li>Exact schemas, chunk sizing, prompt templates</li>\\n            <li>Fine-grained retry/backoff parameters</li>\\n            <li>Exact IAM role bindings per resource (unless forced)</li>\\n            <li>Exact SLOs (propose targets at HLD, finalize later)</li>\\n          </ul>\\n        </div>\\n      </div>\\n\\n      <div class=\\"ok\\">\\n        <strong>Rule of thumb:</strong> if it affects security/privacy, cost materially, operability, or requires another team\u2019s provisioning,\\n        it must be decided (or at least bounded) at HLD.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"architecture\\">2) Reference architecture (GCP-aligned)</h2>\\n    <div class=\\"card\\">\\n      <h3 id=\\"request-path-query-time\\">Request path (query time)</h3>\\n      <ol>\\n        <li>User signs in via Google Workspace (OIDC) \u2192 SPA gets <code>access_token</code>.</li>\\n        <li>SPA calls backend API with <code>Authorization: Bearer ...</code>.</li>\\n        <li>Backend validates JWT, maps to <code>user_id</code>/<code>tenant_id</code>, enforces group/corpus gates.</li>\\n        <li>Backend retrieves chunks (strict filters) \u2192 packs context \u2192 calls LLM \u2192 returns answer with citations.</li>\\n        <li>Backend writes audit logs (user, tenant, docs cited, timings).</li>\\n      </ol>\\n\\n      <h3 id=\\"ingestion-path-offline\\">Ingestion path (offline)</h3>\\n      <ol>\\n        <li>Document discovered/uploaded \u2192 event published.</li>\\n        <li>Worker extracts text + metadata \u2192 stores canonical record.</li>\\n        <li>Embeddings/index written to retrieval system with tenant/corpus metadata.</li>\\n      </ol>\\n\\n      <div class=\\"callout\\">\\n        <strong>Core HLD principle:</strong> access control is enforced in the backend and data layers, not in the browser.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"services\\">3) GCP service choices (what we pick, why, alternatives, and constraints)</h2>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"3-1-end-user-identity-google-workspace-sso\\">3.1 End-user Identity (Google Workspace SSO)</h3>\\n      \x3c!--\\n  UPDATED snippet: Org allowlist explanation + where it happens\\n  (Insert this inside section 3.1, right after:\\n    <h3>3.1 End-user Identity (Google Workspace SSO)</h3>\\n   and before the table.)\\n--\x3e\\n\\n<div class=\\"card\\" id=\\"org-allowlist-explainer\\">\\n  <h3 id=\\"quick-concept-what-is-an-org-allowlist\\">Quick concept: What is an \u201cOrg allowlist\u201d?</h3>\\n\\n  <p>\\n    An <strong>Org allowlist</strong> is a \u201cfront door\u201d rule that answers:\\n    <strong>\u201cIs this person allowed to use our application at all?\u201d</strong>\\n    This is separate from tenant isolation (\u201cwhat data can you access once inside?\u201d).\\n  </p>\\n\\n  <div class=\\"ok\\">\\n    <strong>Authentication</strong> (Google login) proves <em>who you are</em>.<br>\\n    <strong>Org allowlist</strong> decides <em>whether you\u2019re allowed to enter</em>.<br>\\n    <strong>Tenant isolation</strong> decides <em>what you can see after you enter</em>.\\n  </div>\\n\\n  <h3 id=\\"where-it-happens-two-common-places\\">Where it happens (two common places)</h3>\\n  <p>\\n    In enterprises, you usually implement the allowlist in one of these places:\\n  </p>\\n\\n  <div class=\\"grid2\\">\\n    <div class=\\"box\\">\\n      <div class=\\"k\\">Option A \u2014 At the IdP (preferred when available)</div>\\n      <p>\\n        You configure access rules at the <strong>Identity Provider</strong> (Google Workspace / your IdP) so only approved users\\n        can complete login for this application.\\n      </p>\\n      <ul>\\n        <li><strong>How:</strong> use Google/IdP app access controls or group-based assignment (only members can use the app).</li>\\n        <li><strong>Effect:</strong> users outside the group often cannot complete sign-in for this app (blocked earlier).</li>\\n        <li><strong>Benefit:</strong> \u201cblocked at the door\u201d before tokens are issued for your app.</li>\\n      </ul>\\n    </div>\\n\\n    <div class=\\"box\\">\\n      <div class=\\"k\\">Option B \u2014 In your application server (common and reliable)</div>\\n      <p>\\n        Your backend (FastAPI) enforces the allowlist on <strong>every request</strong> by checking group membership (or a local allowlist)\\n        after validating the JWT.\\n      </p>\\n      <ul>\\n        <li><strong>How:</strong> verify token \u2192 read identity \u2192 check \u201cis user in approved org group?\u201d</li>\\n        <li><strong>Effect:</strong> user can log in, but your API returns <code>403 Forbidden</code> if not allowed.</li>\\n        <li><strong>Benefit:</strong> uniform enforcement even if IdP-side restrictions are incomplete.</li>\\n      </ul>\\n    </div>\\n  </div>\\n\\n  <div class=\\"callout\\">\\n    <strong>Enterprise best practice:</strong> use <em>both</em> when possible.\\n    <br>\\n    <span style=\\"color: var(--muted);\\">\\n      IdP-side gating reduces exposure and noise; app-side gating guarantees enforcement and supports richer rules (e.g., per-tenant mapping).\\n    </span>\\n  </div>\\n\\n  <h3 id=\\"how-it-looks-in-our-project-google-workspace-group\\">How it looks in our project (Google Workspace group)</h3>\\n  <p>\\n    We define a Google Group like <code>docqa-users@company.com</code>.\\n    Only members are allowed to use the product.\\n  </p>\\n\\n  <pre>Policy (conceptual):\\n1) Verify JWT (signature, issuer, audience, expiry)\\n2) Extract stable identity (issuer + sub, and email if present)\\n3) Check org allowlist:\\n   - if NOT in docqa-users@company.com \u2192 403 \\"not allowed\\"\\n   - if IN group \u2192 continue\\n4) Map user \u2192 tenant_id (domain or DB lookup)\\n5) Enforce tenant/corpus filters on retrieval + data access\\n  </pre>\\n\\n  <h3 id=\\"why-it-exists-common-reasons\\">Why it exists (common reasons)</h3>\\n  <ul>\\n    <li><strong>Security &amp; governance:</strong> limit exposure to approved users only.</li>\\n    <li><strong>Privacy:</strong> reduce risk by restricting who can query sensitive corpora.</li>\\n    <li><strong>Pilot control:</strong> roll out to a small cohort first (execs + EAs), then expand.</li>\\n    <li><strong>Cost control:</strong> LLM usage is expensive\u2014control who can generate traffic.</li>\\n  </ul>\\n\\n  <h3 id=\\"don-t-confuse-this-with-gcp-iam\\">Don\u2019t confuse this with GCP IAM</h3>\\n  <div class=\\"warn\\">\\n    End users typically do <em>not</em> need GCP IAM permissions. They access documents through the application.\\n    The backend uses its own <strong>service identity</strong> (service account / workload identity) to access GCS, DB, secrets, etc.\\n    <br><br>\\n    <strong>Org allowlist</strong> = \u201cCan this user use the app?\u201d\\n    <br>\\n    <strong>Cloud IAM</strong> = \u201cCan this principal access GCP resources (buckets, secrets, projects)?\u201d\\n  </div>\\n</div>\\n      <table>\\n        <thead>\\n          <tr>\\n            <th>Capability</th>\\n            <th>Chosen (HLD)</th>\\n            <th>Why</th>\\n            <th>Alternatives considered</th>\\n            <th>Enterprise constraints / delays</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td>Login + tokens</td>\\n            <td>Google Workspace OIDC (Auth Code + PKCE in SPA)</td>\\n            <td>Standard enterprise SSO; stateless API validation</td>\\n            <td>Identity Platform; custom IdP; IAP in front of app</td>\\n            <td>Token audience/issuer alignment; group claim policy; approval for group gating approach</td>\\n          </tr>\\n          <tr>\\n            <td>Org allowlist</td>\\n            <td>Google Groups gating (e.g., <code>docqa-users@company.com</code>)</td>\\n            <td>Simple \u201callowed to use product\u201d control</td>\\n            <td>App-local allowlist; IAP access policy</td>\\n            <td>Group ownership, membership governance, and audit rules</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n\\n      <div class=\\"warn\\">\\n        <strong>HLD note:</strong> group gating answers \u201cwho can use the app\u201d; tenant isolation answers \u201cwhat data can they access.\u201d\\n        They are related but not the same.\\n      </div>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"3-2-frontend-hosting-react\\">3.2 Frontend hosting (React)</h3>\\n      <table>\\n        <thead>\\n          <tr>\\n            <th>Chosen (HLD)</th>\\n            <th>Why</th>\\n            <th>Alternatives</th>\\n            <th>Delays / internal patterns</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td>Cloud Run (frontend service)</td>\\n            <td>Easy rollout; supports rewrites/headers and enterprise networking patterns if needed</td>\\n            <td>Cloud Storage + Cloud CDN (static); Firebase Hosting</td>\\n            <td>DNS/cert/WAF approvals can be longer than development</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"3-3-backend-compute-fastapi\\">3.3 Backend compute (FastAPI)</h3>\\n      <table>\\n        <thead>\\n          <tr>\\n            <th>Chosen (HLD)</th>\\n            <th>Why</th>\\n            <th>Alternatives</th>\\n            <th>Delays / internal patterns</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td>GKE (Kubernetes)</td>\\n            <td>Enterprise standard for regulated workloads; consistent policy enforcement; supports internal services</td>\\n            <td>Cloud Run (faster to ship); MIG on GCE</td>\\n            <td>Landing zone onboarding, hardened node pools, image scanning gates, network policies, mesh requirements</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n\\n      <div class=\\"callout\\">\\n        <strong>HLD articulation:</strong> \u201cGKE is chosen not because it\u2019s trendy, but because it matches enterprise platform patterns and controls.\u201d\\n      </div>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"3-4-canonical-store-metadata-system-of-record\\">3.4 Canonical store (metadata + system of record)</h3>\\n      <table>\\n        <thead>\\n          <tr>\\n            <th>Chosen (HLD)</th>\\n            <th>Why</th>\\n            <th>Alternatives</th>\\n            <th>Delays / internal patterns</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td>Cloud SQL (PostgreSQL)</td>\\n            <td>Clear system-of-record; relational metadata; supports backstop controls (e.g., RLS) if needed</td>\\n            <td>AlloyDB (scale/perf); Firestore (not ideal for relational workloads)</td>\\n            <td>Private IP setup; KMS key approvals; DBA access model; backups/retention policies</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"3-5-object-storage-raw-docs-extracted-artifacts\\">3.5 Object storage (raw docs + extracted artifacts)</h3>\\n      <table>\\n        <thead>\\n          <tr>\\n            <th>Chosen (HLD)</th>\\n            <th>Why</th>\\n            <th>Alternatives</th>\\n            <th>Delays / internal patterns</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td>Cloud Storage (GCS)</td>\\n            <td>Durable, cheap, standard; fits ingestion pipeline and artifact storage</td>\\n            <td>Filestore (rare); third-party storage (vendor risk)</td>\\n            <td>Uniform bucket-level access, retention policies, VPC-SC restrictions, data residency constraints</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"3-6-retrieval-semantic-search-vector-strict-metadata-filters\\">3.6 Retrieval / Semantic Search (vector + strict metadata filters)</h3>\\n      <p>\\n        At HLD, you choose one path for the pilot and document the fallback/phase-2 alternative.\\n        The key requirement is <strong>strict filtering</strong> (tenant/corpus) to avoid leakage.\\n      </p>\\n\\n      <table>\\n        <thead>\\n          <tr>\\n            <th>Option</th>\\n            <th>When we choose it</th>\\n            <th>Why</th>\\n            <th>Tradeoffs</th>\\n            <th>Delays / internal patterns</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td><strong>Option A: Vertex AI Search / Agent Builder</strong></td>\\n            <td>Pilot needs speed and managed operations</td>\\n            <td>Managed retrieval; fast path; less ops burden</td>\\n            <td>Less low-level control; feature fit must be validated</td>\\n            <td>Service enablement approvals; data classification rules; integration reviews</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Option B: OpenSearch/Elasticsearch on GKE</strong></td>\\n            <td>Need maximum control or org already runs search platform</td>\\n            <td>Full control: hybrid search, filters, scoring, tuning</td>\\n            <td>Higher ops cost; patching/backups/sizing required</td>\\n            <td>Platform onboarding queue; cluster hardening; storage class decisions; backup standards</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n\\n      <div class=\\"ok\\">\\n        <strong>HLD best practice:</strong> choose the simplest option that satisfies strict filtering and governance.\\n        \u201cPerfect retrieval\u201d is not required for pilot, but \u201csafe retrieval\u201d is.\\n      </div>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"3-7-async-ingestion-orchestration-durable-retries\\">3.7 Async ingestion orchestration (durable retries)</h3>\\n      <table>\\n        <thead>\\n          <tr>\\n            <th>Chosen (HLD)</th>\\n            <th>Why</th>\\n            <th>Alternatives</th>\\n            <th>Delays / internal patterns</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td>Pub/Sub + Cloud Tasks (or Workflows if needed)</td>\\n            <td>Durable eventing + retries; survives restarts; rate limiting</td>\\n            <td>GKE-native queues; scheduler jobs; best-effort background tasks</td>\\n            <td>IAM approvals for topics/subscriptions; DLQ standards; audit logging for processing events</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n\\n      <div class=\\"warn\\">\\n        <strong>HLD note:</strong> FastAPI background tasks are fine for light best-effort work, but ingestion needs persistence and retries.\\n      </div>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"3-8-secrets-and-keys\\">3.8 Secrets and keys</h3>\\n      <table>\\n        <thead>\\n          <tr>\\n            <th>Chosen (HLD)</th>\\n            <th>Why</th>\\n            <th>Alternatives</th>\\n            <th>Delays / internal patterns</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td>Secret Manager + Cloud KMS (policy-driven)</td>\\n            <td>Rotation, audit, separation of duties; enterprise standard</td>\\n            <td>Kubernetes secrets (often restricted); third-party vault</td>\\n            <td>Access approval queue; rotation policy alignment; KMS key provisioning in approved region/project</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"3-9-llm-boundary-external-provider-calls\\">3.9 LLM boundary (external provider calls)</h3>\\n      <table>\\n        <thead>\\n          <tr>\\n            <th>Chosen (HLD)</th>\\n            <th>Why</th>\\n            <th>Alternatives</th>\\n            <th>Delays / internal patterns</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td>Backend on GKE calls external LLM via HTTPS (data minimised)</td>\\n            <td>Supports chosen model; keeps enforcement central; can redact/pack context</td>\\n            <td>Vertex AI (Gemini) to keep boundary within GCP; multi-provider routing</td>\\n            <td>Egress allowlisting/proxy; legal/compliance review of provider; data residency policy checks</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n\\n      <div class=\\"ok\\">\\n        <strong>HLD statement to include:</strong> \u201cOnly retrieved snippets are sent to the model. No raw document dumps. Logs never include full snippets.\u201d\\n      </div>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"3-10-observability-and-audit\\">3.10 Observability and audit</h3>\\n      <table>\\n        <thead>\\n          <tr>\\n            <th>Chosen (HLD)</th>\\n            <th>Why</th>\\n            <th>Alternatives</th>\\n            <th>Delays / internal patterns</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td>Cloud Logging + Cloud Monitoring + Cloud Trace (optional: BigQuery for long-term audit analytics)</td>\\n            <td>Required for enterprise support and governance; standard GCP tooling</td>\\n            <td>Splunk/Datadog (if org standard); custom ELK</td>\\n            <td>Retention policy approvals; sensitive logging rules; SIEM integration lead time</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n\\n      <div class=\\"callout\\">\\n        <strong>Audit minimum (per request):</strong> who asked, which tenant, what sources were cited, timings, and outcome (answer/refusal).\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"delays\\">4) Enterprise delays &amp; critical path (what usually takes longest)</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        In banks/airlines, \u201ctime to pilot\u201d is often gated by approvals and provisioning, not coding.\\n        HLD should explicitly call out the critical path so stakeholders understand sequencing.\\n      </p>\\n\\n      <table>\\n        <thead>\\n          <tr>\\n            <th>Workstream</th>\\n            <th>What causes delay</th>\\n            <th>How the AI lead reduces risk</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td>Landing zone / projects</td>\\n            <td>Dev/stage/prod project creation, org policies, shared VPC attachment</td>\\n            <td>Request early; align with platform team templates; keep pilot in one approved project if allowed</td>\\n          </tr>\\n          <tr>\\n            <td>Networking</td>\\n            <td>Private egress, DNS, firewall rules, proxy requirements</td>\\n            <td>Document endpoints early; ask for a standard pattern; avoid custom exceptions</td>\\n          </tr>\\n          <tr>\\n            <td>IAM / service identities</td>\\n            <td>Least-privilege reviews, approvals, periodic reviews</td>\\n            <td>Provide role matrix; use standard roles; limit resources touched in pilot</td>\\n          </tr>\\n          <tr>\\n            <td>Data owner approval</td>\\n            <td>Corpus sign-off, classification review, explicit exclusions</td>\\n            <td>Propose a bounded corpus; provide an exclusion list; show audit controls</td>\\n          </tr>\\n          <tr>\\n            <td>Security/privacy review</td>\\n            <td>Threat model, logging policy, model boundary policy</td>\\n            <td>Bring a short threat model + mitigations; demonstrate \u201ccite or refuse\u201d; propose redaction policy</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n\\n      <div class=\\"warn\\">\\n        <strong>HLD maturity signal:</strong> You\u2019re not surprised by these delays \u2014 you plan around them and assign owners.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"howtopresent\\">5) How to present this in an architecture review</h2>\\n    <div class=\\"card\\">\\n      <h3 id=\\"recommended-presentation-structure\\">Recommended presentation structure</h3>\\n      <ol>\\n        <li><strong>Start with trust boundaries</strong> (what data leaves the boundary to the model)</li>\\n        <li><strong>Show identity and access enforcement</strong> (group gate + tenant/corpus gates)</li>\\n        <li><strong>Declare the chosen services</strong> with 1\u20132 sentences of why</li>\\n        <li><strong>List alternatives considered</strong> and why not now</li>\\n        <li><strong>End with risks + mitigations</strong> and the approval asks</li>\\n      </ol>\\n\\n      <div class=\\"ok\\">\\n        <strong>Reviewer-friendly line:</strong> \u201cWe are optimising for a safe pilot. Where a managed service reduces operational risk, we choose it.\\n        Where strict filtering and control are essential, we use a search platform that enforces metadata filters.\u201d\\n      </div>\\n\\n      <h3 id=\\"example-decision-statement-format-copy-paste\\">Example \u201cDecision statement\u201d format (copy/paste)</h3>\\n      <table>\\n        <thead>\\n          <tr>\\n            <th>Decision</th>\\n            <th>Chosen</th>\\n            <th>Why</th>\\n            <th>Alternatives</th>\\n            <th>Phase-2 note</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td>Retrieval layer</td>\\n            <td>Vertex AI Search (pilot)</td>\\n            <td>Fast to ship; managed ops; meets strict filtering needs (to be validated)</td>\\n            <td>OpenSearch on GKE</td>\\n            <td>Move to OpenSearch if advanced tuning is required</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n    </div>\\n\\n    <div class=\\"tr-note\\">\\n      <strong>HLD deliverable</strong>\\n      Turn the decisions in this chapter into an\\n      <strong>Architecture Review Pack</strong> containing the HLD sections,\\n      system and trust-boundary diagrams, decision tables, risks, assumptions,\\n      and phase-two alternatives.\\n    </div>\\n  </div>"}'),d={title:"HLD Service Selection (GCP): Exec Document Q&A Pilot \u2014 Choices, Alternatives, Enterprise Delays",slug:"/part1-enterprise-ai-delivery/07-hld-service-selection",description:"This tutorial converts our service-selection discussion into a High-Level Design section you can drop into an Architecture Review Pack. It uses concrete GCP services, includes alternatives considered, and highlights e...",sidebar_label:"7. HLD and service selection",pagination_label:"7. HLD and service selection",hide_title:!0,hide_table_of_contents:!0},l=void 0,c={},h=[];function p(e){return(0,i.jsx)(a.A,{content:o})}function u(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(p,{...e})}):p()}}}]);